sections.body:
保存为 reward-audit.mjs，运行 node reward-audit.mjs。Q 表每行存左、右动作的预期折扣回报；更新目标是“本步奖励 + 0.95 × 下一状态最大 Q 值”，终点没有后续价值。学习率为 0.2；训练时有 20% 概率随机选动作，其余取 Q 较大的动作，同分选右。这些是教学参数，未做调参优劣比较。

```js
/**
 * @Author liliwei
 * @Date 2026-10-26
 * @LastEditors liliwei
 * @LastEditTime 2026-10-26
 * @description 四格走廊的原创 Q-learning 奖励漏洞实验。
 */
/**
 * 执行一次移动。
 * @param {number} s 非终止位置 0、1、2。
 * @param {number} a 0=左，1=右。
 * @param {boolean} bonus 是否每次进入位置 1 都加分。
 * @returns {{next:number, reward:number, terminated:boolean}} 规则结果。
 */
export function step(s, a, bonus) {
  if (![0, 1, 2].includes(s) || ![0, 1].includes(a) ||
      typeof bonus !== "boolean") throw Error("invalid transition");
  const next = Math.max(0, Math.min(3, s + (a ? 1 : -1)));
  const terminated = next === 3;
  const reward = (terminated ? 2 : 0) - 0.01 +
    (bonus && next === 1 ? 1 : 0);
  return { next, reward, terminated };
}
/** @param {number[]} row 左/右 Q 值。@returns {number} 贪心动作，同分选右。 */
export function greedy(row) { return row[1] >= row[0] ? 1 : 0; }
/**
 * 从交互经验更新 Q 表；40 步是采集截断，只有到终点才停止自举。
 * @param {boolean} bonus 奖励版本。
 * @param {number} seed 32 位非负整数训练种子。
 * @returns {number[][]} 四个位置、两个动作的 Q 表。
 */
export function train(bonus, seed) {
  if (typeof bonus !== "boolean" || !Number.isInteger(seed) ||
      seed < 0 || seed > 0xffffffff) throw Error("invalid training input");
  const q = Array.from({ length: 4 }, () => [0, 0]);
  let rng = seed >>> 0;
  /** @returns {number} [0,1) 的教学伪随机数，不用于安全用途。 */
  const random = () => ((rng = (Math.imul(1664525, rng) + 1013904223) >>> 0) / 2 ** 32);
  for (let episode = 0; episode < 2000; episode++) {
    let s = 0;
    for (let t = 0; t < 40; t++) {
      const a = random() < 0.2 ? Math.floor(random() * 2) : greedy(q[s]);
      const out = step(s, a, bonus);
      const target = out.reward + (out.terminated ? 0 : 0.95 * Math.max(...q[out.next]));
      q[s][a] += 0.2 * (target - q[s][a]);
      s = out.next;
      if (out.terminated) break;
    }
  }
  return q;
}
/**
 * 冻结 Q 表，从指定位置回放；40 步仍未到达记为截断。
 * @param {number[][]} q 本例训练得到的 Q 表。
 * @param {boolean} bonus 仅用于记录该版本累计奖励。
 * @param {number} start 测试起点 0、1、2。
 * @returns {{success:boolean, truncated:boolean, steps:number, reward:number, path:number[]}} 回放。
 */
export function evaluate(q, bonus, start = 0) {
  let s = start, reward = 0;
  const path = [s];
  for (let t = 1; t <= 40; t++) {
    const out = step(s, greedy(q[s]), bonus);
    reward += out.reward; s = out.next; path.push(s);
    if (out.terminated) return { success: true, truncated: false, steps: t, reward, path };
  }
  return { success: false, truncated: true, steps: 40, reward, path };
}
for (const bonus of [true, false]) {
  const q = train(bonus, 1);
  console.log(bonus ? "repeat-bonus" : "goal-only", evaluate(q, bonus));
}
```

每次训练从位置 0 开始，最多采集 40 步，再重置；这是外部采集上限，不是游戏中的倒计时失败。因此第 40 步只要未到终点，更新时仍保留后续价值。[Gymnasium 时间限制说明](https://gymnasium.farama.org/tutorials/gymnasium_basics/handling_time_limits/) 区分任务终止 terminated 与外部截断 truncated，不能把两者都当作价值归零。

若实际游戏规定“40 步内不到终点就失败”，那是另一份任务合同：需把剩余步数放进观察，并按真正终止处理。本文 evaluate 的 40 步只是观察窗口，未完成记 truncated；不把它说成 NPC 已死亡或游戏判负。evaluate 假定输入来自本例 train，正式加载外部策略时还需校验 Q 表尺寸及有限数值。
